var e={"guide.intro":`A guided tour of Harness, with examples written for you.`,"guide.case.new":`Everything is new here: the guide starts from zero and Opus writes examples for what you want to do.`,"guide.case.import":`Harness found your import: Opus uses what you brought (projects, memory) to write the examples.`,"guide.case.existing":`You already use Harness: the guide uses your own sessions and agents as examples, and shows what you have not tried yet.`,"guide.resumeDesc":`You stopped at step {n} of {total}.`,"guide.resume":`Resume where I left off`,"guide.restart":`Start again`,"guide.level.beginner":`Beginner`,"guide.level.beginnerDesc":`I am discovering Claude and Harness. Show me step by step, with simple examples.`,"guide.level.intermediate":`Intermediate`,"guide.level.intermediateDesc":`I already use Claude or another agent. Show me what Harness adds, with examples that go further.`,"guide.notNow":`Close, I don't need it`,"guide.mode.full":`Full tour (about 5 min)`,"guide.mode.fullDesc":`Everything: sessions, Zones and Tabs, memory, agents, scheduled jobs, phone, pages to switch on.`,"guide.mode.partial":`Partial tour (about 2 min)`,"guide.mode.partialDesc":`The essentials, plus only what you want to use (the recommended ones are ticked):`,"guide.use.automate":`Automate (agents, jobs, tasks)`,"guide.use.phone":`Phone and Telegram`,"guide.use.code":`Code and Git`,"guide.use.sites":`Sites and servers`,"guide.use.mail":`E-mail`,"guide.use.team":`Working with others`,"guide.use.content":`Files, documents, media`,"guide.recommended":`Recommended`,"guide.start":`Start`,"guide.pause":`Pause the guide`,"guide.pauseShort":`Pause`,"guide.featureOff":`This page is switched off. Switch it on to follow this step (Settings -> Features turns it off again).`,"guide.enable":`Switch on`,"guide.writing":`Opus is writing an example for you…`,"guide.failed":`No example this time.`,"guide.retry":`Try again`,"guide.try":`Try it`,"guide.tryHint":`The message goes into a new session: read it, change it if you like, then send it. The guide waits on the right edge of the screen.`,"guide.finish":`Finish`,"guide.dock":`Guide · step {n}/{total}`,"guide.continue":`Continue`,"guide.later":`Later (Help -> Getting started guide)`,"guide.welcome.title":`Welcome to Harness Maxxing`,"guide.welcome.body":`Harness runs Claude on your own server: it works in real folders, remembers what matters and keeps working when you are away.`,"guide.welcome.tip":`Pause at any time: the guide waits on the right edge of the screen, and Help (?) at the bottom left brings it back.`,"guide.nav.title":`Everything is in this sidebar`,"guide.nav.body":`Dashboard, sessions, files, settings: every page is here. On a phone, ☰ at the top left opens the same menu.`,"guide.nav.tip":`Drag the pages to reorder them, and G then a letter jumps to a page (G S = Sessions).`,"guide.tree.title":`Projects, topics, sessions`,"guide.tree.body":`Your work is split into projects, each split into topics. A topic is a folder Harness works in, with its own memory; every conversation in it is a session.`,"guide.tree.tip":`Drag a session onto another topic to move it; its … menu (or a right-click) adds it to your favorites.`,"guide.first-prompt.title":`Your first request`,"guide.first-prompt.body":`A session is a conversation with Claude in a topic. It writes real files there, that you open in one click.`,"guide.first-prompt.tip":`Attach files by dropping them on the message box, or dictate with the mic. A message sent while Claude works waits its turn.`,"guide.memory.title":`Harness remembers`,"guide.memory.body":`Every topic has a memory.md read by each of its sessions, on top of the project's and the global one. Here you see and edit them all.`,"guide.memory.tip":`Say “remember that…” in a session: the fact goes to the right memory and the next session knows it.`,"guide.view-switch.title":`Zones or Tabs`,"guide.view-switch.body":`Zones show several sessions side by side (columns, grid); Tabs show one at a time with the others as chips. This button switches, the lit one works right now.`,"guide.view-switch.tip":`Alt+T switches too. In Zones, drag a session by its grip to put it elsewhere; your choice follows you from computer to phone.`,"guide.palette.title":`Find anything`,"guide.palette.body":`⌘K / Ctrl+K searches files, sessions, topics, settings and actions. The fastest way around.`,"guide.palette.tip":`Type a few letters of what you are looking for, even the name of a setting, then Enter.`,"guide.agents.title":`Agents work for you`,"guide.agents.body":`An agent is a lasting role in a topic: it starts on its own (a schedule, an e-mail, a webhook, another agent) and keeps to a daily budget.`,"guide.agents.tip":`No form to fill: ask for an agent in a session, Harness asks only what is missing. Switch one off in one click on the Agents page.`,"guide.agents-sessions.title":`Agents, from the sessions side`,"guide.agents-sessions.body":`Every run of an agent is a session in its topic: open it to see what it did, reply in it, or hand it work from any session.`,"guide.agents-sessions.tip":`@ in the message box mentions another session or an agent; a group gathers 2 to 6 agents in one conversation with you.`,"guide.crons.title":`At set times`,"guide.crons.body":`Scheduled jobs run a command or a prompt every day, every hour, or once later, with a report if you want one.`,"guide.crons.tip":`Simply say “every morning at 8, …” or “remind me in 10 minutes” in a session.`,"guide.tasks.title":`Tasks`,"guide.tasks.body":`Your board of things to do, that Harness reads and updates too.`,"guide.tasks.tip":`“What is due today?” in a session reads the board for you.`,"guide.telegram.title":`From your phone`,"guide.telegram.body":`Link a Telegram bot to continue any session, start one, send voice messages and photos, and get the alerts.`,"guide.telegram.tip":`Harness also installs as an app: Share -> Add to Home Screen on iPhone, the browser menu on Android, with notifications.`,"guide.code.title":`Code and Git`,"guide.code.body":`Harness works in your repositories. Under each answer, the Changes view shows the diff of the turn: undo a file, commit, push, open a pull request.`,"guide.code.tip":`“Revert to before this message” (menu of a message) undoes what a turn changed: you can try anything.`,"guide.sites.title":`Sites and servers`,"guide.sites.body":`Infra shows every site, database, bucket, domain and server, with its status; Harness puts things online on this server the standard way.`,"guide.sites.tip":`“Where is X?” or “is my site up?” in a session: Harness checks it live.`,"guide.mail.title":`E-mail`,"guide.mail.body":`Your mailboxes in Harness: it reads, sorts, files and drafts the answers; nothing leaves without your OK.`,"guide.mail.tip":`An agent can get its own mailbox, with the senders it may answer.`,"guide.team.title":`With other people`,"guide.team.body":`Team: chat with your contacts and groups, and share a session or a file with them.`,"guide.team.tip":`Harness can write to a contact for you, only when you ask it to.`,"guide.content.title":`Files and documents`,"guide.content.body":`Every file Harness makes (PDF, images, videos, documents) opens and is edited here; the paths in its answers are clickable.`,"guide.content.tip":`In a document opened from a session, select a passage and Comment: the session reads your comments.`,"guide.safety.title":`Keep your work safe`,"guide.safety.body":`The backup copies your memory and workspace to a private GitHub repository: the way to get everything back, or to move to a new server.`,"guide.safety.tip":`Keys and passwords go in Settings -> Keys, never in a message: sessions and scripts read them from there.`,"guide.features.title":`Switch on what you need`,"guide.features.body":`Optional pages (Tasks, Agents, E-mail, Git, Infra, Team, Browser, Devices…) stay off until you need them: one click here.`,"guide.features.tip":`Settings -> Appearance changes the colours, the fonts and the layout; the dashboard's Edit layout moves its cards.`,"guide.health.title":`Server health`,"guide.health.body":`This dot turns orange or red when something needs attention: disk, memory, a failed job, a stopped service.`,"guide.health.tip":`Click it for the details and the fix; updates are announced here too.`,"guide.final.title":`You're all set`,"guide.final.body":`Some next steps, chosen for you. The guide stays in Help (?) at the bottom left.`,"guide.final.tip":`Learn by doing: the interactive tutorial walks you through real exercises.`,"tour.step":`Step {n} of {total}`,"tour.next":`Next`,"tour.back":`Back`,"tour.skip":`Skip the tour`};export{e as default};